from __future__ import unicode_literals

from functools import partial
import unittest
from ute_common_util.test.temp import path_to_resource
from ute_common_config_files.scfc.exceptions import NoSuchParameter
from ute_common_config_files.scfc.scfc import Scfc

path_to_resource = partial(path_to_resource, __name__)
DIST_NAME = 'MRBTS-1/BTSSCL-1/LCELL-1'


class TestListParam(unittest.TestCase):

    @path_to_resource('resources/scfc/complex_param.xml')
    def test_find_param_by_name_found(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        param = list_param.find_param('existingParam')
        self.assertEqual(param.xml.tag, '{raml21.xsd}p')
        self.assertEqual(param.name, 'existingParam')

    @path_to_resource('resources/scfc/complex_param.xml')
    def test_find_param_by_name_not_found(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        with self.assertRaises(NoSuchParameter):
            list_param.find_param('notExistingParam')

    @path_to_resource('resources/scfc/complex_param_duplicated.xml')
    def test_find_param_by_name_and_value_found(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        param = list_param.find_param('existingParam', param_value='456')
        self.assertEqual(param.xml.tag, '{raml21.xsd}p')
        self.assertEqual(param.xml.text, '456')

    @path_to_resource('resources/scfc/complex_param_duplicated.xml')
    def test_find_param_by_name_and_value_not_found(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        with self.assertRaises(NoSuchParameter):
            list_param.find_param('existingParam', param_value='789')
        with self.assertRaises(NoSuchParameter):
            list_param.find_param('notExistingParam', param_value='123')

    @path_to_resource('resources/scfc/empty_list.xml')
    def test_add_param_to_empty_list(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        added_param = list_param.add_param('newParam', 'newValue')
        self.assertEqual(list_param.find_param('newParam').xml, added_param.xml)
        self.assertEqual(added_param.value, 'newValue')

    @path_to_resource('resources/scfc/empty_list_with_item.xml')
    def test_add_param_to_empty_list_with_item(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        added_param = list_param.add_param('newParam', 'newValue')
        self.assertEqual(list_param.find_param('newParam').xml, added_param.xml)
        self.assertEqual(added_param.value, 'newValue')

    @path_to_resource('resources/scfc/complex_param.xml')
    def test_add_param_to_nonempty_list(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        added_param = list_param.add_param('newParam', 'newValue')
        self.assertEqual(list_param.find_param('newParam'), added_param)
        self.assertEqual(added_param.value, 'newValue')
        self.assertEqual(list_param.find_param('existingParam').value, '123')

    @path_to_resource('resources/scfc/empty_list.xml')
    def test_add_duplicated_params(self, scfc_path):
        list_param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_list_param('existingList')
        added_param_1 = list_param.add_param('newParam', 'newValue1')
        added_param_2 = list_param.add_param('newParam', 'newValue2')
        self.assertEqual(list_param.find_param('newParam', 'newValue1'), added_param_1)
        self.assertEqual(added_param_1.value, 'newValue1')
        self.assertEqual(list_param.find_param('newParam', 'newValue2'), added_param_2)
        self.assertEqual(added_param_2.value, 'newValue2')
        self.assertNotEqual(added_param_1.xml.getparent(), added_param_2.xml.getparent(), 'Added params should be in separate <item>s')
